        TezVertexID vId = TezVertexID.getInstance(dagId, i);
        Vertex v = dag.getVertex(vId);
        Assert.assertEquals(VertexState.RUNNING, v.getState());
        if (i < 2) {
            Assert.assertEquals(0, v.getDistanceFromRoot());
        } else if (i == 2) {
